const IMG = "/dubai-event/awardees-dubai-2021";

export interface Awardee {
    name: string;
    title: string;
    image: string | null;
    bio: string;
}

export const awardees: Awardee[] = [
    { name: "Wayne Barnett", title: "Senior Legal Counsel, SAP", image: `${IMG}/wayne-barnett-v2.png`, bio: "Australian qualified lawyer with strong commercial and IT background gained from more than 25 years\u2019 experience working in Australia, Denmark, England, Malaysia, Indonesia, Korea, Middle East, Pakistan and Africa. For the last 15 years, Wayne has been based in Dubai and is now in his 10th year at SAP. He negotiates and advises on software licensing, cloud services and professional consulting services and has supported a rapidly growing business for many years in a demanding and vibrant sales environment working with some of the most prominent companies in the world and involved in more than 25 industry sectors including public sector, oil and gas, defense, retail, airlines and banking." },
    { name: "Arzu \u00d6zgen", title: "Legal Affairs Manager, Tum Ictur A.S.", image: `${IMG}/arzu-ozgen.jpg`, bio: "Arzu Ozgen is a Legal Affairs Manager of Tum Ictur A.S. (Food and Beverage Operator of Istanbul Airport) in Istanbul, Turkey. Prior to Istanbul Airport, Ozgen was a Senior Lawyer at Ata Holding A.S. and she was manager of the legal team and advocate of Tab Gida Sanayi Ticaret A.S. (an operating subsidiary company of ATA Holding) with full legal responsibility of BURGER KING, POPEYES, ARBY'S and SBARRO restaurants' operations and all litigation files. She specialized in Franchise Law, Labour Law and Corporate Law." },
    { name: "Asim Habib", title: "Solicitor, England & Wales", image: `${IMG}/asim-habib.jpg`, bio: "Asim an England and Wales qualified Solicitor. Versatile and experienced, he offers skills in the drafting, review and negotiation of legal agreements with government and private sector clients for projects in the construction, energy, transport, oil and gas, and technology industries in multiple jurisdictions. Over the last ten years, he has supported and advised on regulations and policies of national and international importance in a variety of sectors and more currently advise on all legal issues relating to the digital transformation of automation and energy management and predictive maintenance for a variety of projects including Data Centers, buildings and homes." },
    { name: "Aylin \u00d6nen", title: "Managing Associate, BATI Lawyers & Advisers", image: `${IMG}/aylin-onen.jpg`, bio: "Aylin is the Managing Associate at BATI Lawyers & Advisers. She is specialized in Intellectual Property Law and practices in the areas of trademark, patent, design, copyright, unfair competition and domain name disputes and represents Clients before Turkish Courts and arbitrary tribunals. She advises broad range of intellectual property issues and provide professional assistance to the clients for creating an intellectual property management strategy." },
    { name: "Rania Ghosheh", title: "Senior Partner, Ittqan Consulting Services", image: `${IMG}/rania-ghosheh.png`, bio: "Founding member and Senior Partner at Ittqan Consulting Services in Palestine. Partner and legal consultant for Mena Apps L.L.C. (ICT start ups accelerator and Angel Investor), Jordan. She has been a mentor for start-ups in legal and business matters throughout the region. Regionally and globally, she participates as judge in pitching competitions. Adv. Ghosheh is a Business Lawyer with long experience in corporate and business law, intellectual property law, contract negotiation and drafting, as well as other sectors." },
    { name: "Faisal Sherwani", title: "Partner, L&L Partners Law Offices", image: `${IMG}/faisal-sherwani.jpg`, bio: "Faisal Sherwani is an Advocate-on-Record, Supreme Court of India and is currently a Partner in the Dispute Resolution practice at L&L Partners Law Offices, New Delhi. With experience of over a decade in the field of dispute resolution and dispute advisory services, he has a deep understanding of procedural and substantive issues of law. He regularly practices before the Hon'ble Supreme Court of India as well as the Hon'ble High Courts at Delhi, Bombay, Karnataka, Telangana, Allahabad and Madras as also the NCLT and NCLAT. He has a host of reported Judgments to his credit. He continuously advises and acts for clients on a range of subjects such as constitutional law aspects, arbitration laws, corporate, commercial and insolvency laws, labor legislations, white-collar crimes and penal laws." },
    { name: "Balakrishna Gopalakrishnan", title: "Legal Advisor, Arcil Mumbai", image: `${IMG}/balakrishna-gopalakrishnan.jpg`, bio: "A dynamic and result-oriented legal professional with over four decades of experience in legal areas encompassing Banking, Corporate, Capital Market and Business Laws, Cross Border Transaction and Procedures, Human Resource Issues and Employee Grievance Redressal, Litigation and International Arbitration. Formerly worked as Legal Advisor heading the Legal Operations & Human Resources Group of Asset Reconstruction Company (India) Ltd. (Arcil), Mumbai, one of India's largest and premier ARCs. Prior to that, and for 14 years, was the President and Head of the Law Department of Axis Bank Ltd." },
    { name: "Dr. G.V. Rao", title: "Senior Advocate, Supreme Court of India", image: `${IMG}/dr-gv-rao.jpg`, bio: "Dr. G. VENKATESH RAO is a Senior Advocate, of the Supreme Court of India with 34 years of practice. His areas of specialization are Litigation, Legal Advice, Govt and academics, in the field of Constitutional, Law, Taxation, International Law, Corporate Law, Intellectual Property, and Cyberlaws, Telecom, Economic offences, Shipping and Banking. Dr.Rao started his career, as a Counsel, at the office of the Attorney General for India for 5 yrs. Later he was an Independent Central and state Government Counsel for about 22yrs, while continuing private practice. He has also been associated with a numerous, domestic and international universities, public policy institutions, U.N and other global bodies, for academics and faculty contribution. He has been an office-bearer of prestigious organisations like, Global Policy insights London, World Peace Congress, Nakhonayok Thailand, of which he was Vice-President as also for Global Education Law Forum (GELF) Amsterdam. And in such positions been a representative to several UNESCO and U.N. Conferences." },
    { name: "Kiran Laxman Padalkar", title: "Partner, India Law Alliance", image: `${IMG}/kiran-padalkar.jpg`, bio: "With a decade of experience in real estate, arbitration, general and commercial litigation, Kiran believes his mentors in the profession, paved the path for his success. He knows that it is critical to building a solid team, which can be strengthened on the foundation of care, to ensure that they will be invested and aspire to do their best. Kiran began his career with Mansukhlal Hiralal & Co. first as a paralegal and then as an associate. He has been at India Law Alliance since December 2013. He was promoted to Partner in October 2019." },
    { name: "Tushar Agarwal", title: "Advocate, Criminal & Constitutional Law", image: `${IMG}/tushar-agarwal.jpg`, bio: "His practice primarily focuses on Criminal Law, Constitutional Law and Commercial Arbitration. His Chamber caters to all the needs of the litigants starting from Legal Opinion & Legal Drafting to presenting arguments before the court of law. Mr. Agarwal was one of the assisting counsels representing Dr. Shashi Tharoor in a famous Sunanda Pushkar Death Case. He has also appeared in few pro bono cases with Senior Counsels representing Association of Victims of Uphaar Tragedy, Association of Victims of Meerut Fire Tragedy etc. Mr. Agarwal is currently handling few important matters relating to corruption, corporate frauds, money laundering & GST tax evasion being investigated by the Central Bureau of Investigation (CBI), Serious Fraud Investigation Office (SFIO), Enforcement Directorate (ED) & Director General GST Intelligence (DGGI) respectively." },
    { name: "Florian Koemm", title: "General Counsel, Siemens Energy ME", image: `${IMG}/florian-koemm.jpg`, bio: "Following his primary education and civil service in Cologne, Germany, Dr. Florian Koemm studied law at the Universities of Passau and Bonn, Germany. In honor of his accomplishments he received a post-graduate scholarship and received a PhD in finance law by the University of Bonn. Dr. Koemm started his career with Siemens in Munich advising Siemens Financial Services and later advising its Rolling Stock Business in Erlangen. Today, he is the General Counsel for Siemens Energy in the Middle East, based in Dubai." },
    { name: "Ayush Agarwala", title: "Partner, K Law (Mumbai)", image: `${IMG}/ayush-agarwala.jpg`, bio: "Ayush heads the disputes practice in the Mumbai office of the firm. Prior to joining K Law, Ayush was associated with some of the largest firms in India, AZB & Partners and Khaitan & Co. Ayush has advised several corporate power houses and multinational companies, both domestic and international spanning various industries and sectors. He has extensive experience in sectors including shareholder disputes, infrastructure, insurance, petrochemicals, debt equity financing, telecom, hospitality, manufacturing, information technology and consumer. Ayush has advised and acted in various high-stake matters and matters which led to landmark judgments being passed by courts in India." },
    { name: "Shikher Deep Aggarwal", title: "Partner Designate, L&L Partners", image: `${IMG}/shikher-deep-aggarwal.jpg`, bio: "Shikher Deep Aggarwal is a Partner Designate in India's leading law firm \u2013 L&L Partners Law Offices. Shikher has a demonstrative career with experience of almost a decade at the bar. He is proficient in all kinds of legal disputes with a passion for dealing with cases related to penal laws, white-collar crimes, information technology laws, gambling laws, arbitration and commercial laws, etc. He is a specialist in advising clients on a wide variety of legal issues and navigates them through and out of their problems. His distinctive authority in dealing with massive documentary burdens in high stake matters and effectiveness in bringing out applicable points of law and procedure has seen a rise of esoteric popularity amongst his clients." },
    { name: "Mumtaz Bhalla", title: "Specialist, Domestic & International Arbitration", image: `${IMG}/mumtaz-bhalla.jpg`, bio: "Mumtaz has over 14 years of experience in the field of litigation and dispute resolution. She specialises in Domestic and International Arbitrations. She has a considerable amount of experience in the aviation sector, medical sector, real estate, construction, and civil-commercial sector, with her being the preferred choice for several domestic and international clients. She also possesses a wide range of experience in civil trial, criminal trial, appeals, consumer disputes, domestic and international arbitration. She also specialises in conducting compliance workshops for Companies. She has advised and represented several multi-national companies and organisations regarding appropriate strategies to be adopted at various stages of litigation and arbitration. She is liked by her clients for providing them with effective and quick solutions for every issue." },
    { name: "Sanchita Ain", title: "Advocate-on-Record, Supreme Court of India", image: `${IMG}/sanchita-ain.jpg`, bio: "Sanchita Ain is an Advocate-on-Record in the Supreme Court of India. With an experience of over nine years of experience in the field of law, she has handled complex matters before the Supreme Court, High Courts, and other forums in the country. These include landmark constitutional law cases like linking of PAN with Aadhaar, triple talaq, 2G spectrum case, affirmative action, rights of minority institutions, land acquisition cases, and matters relating to civil, corporate, competition, service, and family laws. She holds the prestigious LLM degree in International Human Rights Law with distinction from the University of Essex." },
    { name: "Meenakshi Acharya", title: "Founder, RMA Legal", image: `${IMG}/meenakshi-acharya.jpg`, bio: "She has over 14 years of versatile experience in mergers & acquisitions, private equity and investments, foreign investment policies (FEMA), corporate & commercial transactions; capital market, e-commerce, real estate, infrastructure, employment & labor matters. Meenakshi's experience in working with top law firms of India like the AZB & Partners, Thakker & Thakker, ARA Law, and Singhania & Co., has helped her to guide RMA Legal to its current position in the market." },
    { name: "Shalinee Fernandez", title: "Regional Legal Counsel Asia-Pacific, ATOS", image: `${IMG}/shalinee-fernandez.jpg`, bio: "With close to 19 years of experience, 5 years in private practice as a partner undertaking both litigation and corporate work in the areas of general civil litigation, employment, family law, banking, industrial relations, and corporate winding-up proceedings. Shalinee spent the last 14 years as a corporate in-house legal counsel in the ICT and manufacturing industry- including being Regional Legal Counsel Asia-Pacific for ATOS, a French Information, Communications and Technology multinational corporation heading all legal & compliance matters for the Australian continent, New Zealand, Malaysia, Indonesia and other countries in the APAC region." },
    { name: "Dr. Sunanda Bharti", title: "Faculty, Law Centre-I, University of Delhi", image: `${IMG}/dr-sunanda-bharti.jpg`, bio: "Dr. Sunanda Bharti has a rich experience of teaching at Law Centre-I, Faculty of Law, the University of Delhi for the past 15 plus years (year of entering this data is 2021). She has a number of published works to her credit on various aspects of Intellectual Property Laws, Foetal Rights and Mediation. She is the Project Lead for Law Team in 'RISHII'-- Resources for Internationalisation of Higher Educational Institutions in India, an International Project under the Erasmus+ Programme funded by the European Commission\u2014in collaboration with the University of Deusto, Bilbao Spain and the Tuning Academy." },
    { name: "Zafar Khurshid", title: "Founding Partner, TKC LLP", image: `${IMG}/zafar-khurshid.jpg`, bio: "Zafar Khurshid is a graduate of St. Stephen's College and the Faculty of Law, Delhi University. Following his LLB he worked in the Supreme Court in the office of the Additional Solicitor General, before migrating to England where he studied Intellectual Property Law at Queen Mary, University of London, graduating with Distinctions in each of his courses. He went to spend two years at St. Edmund Hall, University of Oxford reading for the BCL and an M.Phil in Law focusing on Intellectual Property Law. He returned to India in 2017 and spent the next three years assisting a Senior Advocate in the Hon'ble Supreme Court of India, Hon'ble High Court of Delhi, as well as various tribunals, such as the NCLAT and TDSAT. In 2020 he became one of the Founding Partners of Talwar Khurshid Chauhan (TKC) LLP" },
    { name: "Jouhayna Amr", title: "Legal Counsel, Emirates Integrated Telecommunications (DU)", image: `${IMG}/jouhayna-amr.jpg`, bio: "Jouhayna worked in private practice for 8 years in Lebanon in Intellectual Property, Commercial and Corporate Law and Litigation before she moved to Dubai in 2011. Her In house experience includes working in the FMCG industry with Nestle Middle East FZ LLC, followed by Mastercard. She is currently working with Emirates Integrated Telecommunications Company known as DU." },
    { name: "Divyam Agarwal", title: "Partner, J. Sagar Associates", image: `${IMG}/divyam-agarwal.jpg`, bio: "Divyam is a Partner with J. Sagar Associates and a member of the firm's Dispute Resolution practice. He is a dual-qualified Indian Advocate and Solicitor, England & Wales and has developed a niche for advising on complex issues arising out of multiple jurisdictions. He is a qualified Advocate-on-Record at the Supreme Court of India and has been regularly engaged in contentious and high-stakes disputes, which have resulted in landmark judgments. Divyam is a leading practitioner of arbitration law, and has represented several multinational corporations, banks, financial institutions, and business houses in high-stakes domestic, international commercial arbitrations." },
    { name: "Prachi Agarwal", title: "Partner, Anand and Anand", image: `${IMG}/prachi-agarwal.jpg`, bio: "Ms. Prachi is a licensed attorney in the Commonwealth of Virginia and is registered with the Bar Council of Delhi. She is an expert in the field of Patent Litigation and Legal Research while having detailed knowledge of Trademarks, Copyrights and Designs. Having more than 10 publications. Ms. Agarwal worked as a patent prosecution assistant at Ditthavong Mori & Steiner, P.C (Virginia) before starting her journey at Anand and Anand. She is now a partner at Anand and Anand and is intricately involved in intellectual property litigation including Patents, Trademarks, Copyright and Designs." },
    { name: "Seyed Mohammad Azin", title: "Advocate & Academic, University of Tehran", image: `${IMG}/seyed-mohammad-azin.jpg`, bio: "Seyed Mohammad Azin is a well-known lawyer and academic person in Iran and worldwide. He has a Ph.D. in Civil Law from University of Tehran, where he got his LLM and BA in law, as well. Now, he is a scientific board member and senior researcher in Royan Institute for reproductive medicine and stem cell. Meanwhile, he practices law as an expertized advocate and the manager of \u201cDr.Azin Law Clinic\u201d. Furthermore, Azin teaches in \u201cUniversity of Science and Culture\u201d, mostly in the fields of civil law and Islamic jurisprudence. Azin has published many legal articles in English and Persian, mainly focusing on medical law and ethics. These days, his concentration is on the Artificial Intelligence Law and analyzing AI moral status considering recent accelerating technologic developments." },
    { name: "Jash J. Dalia", title: "Partner, Palladium Legal", image: `${IMG}/jash-dalia.jpg`, bio: "He is a Partner at Palladium Legal, a global Law Firm, he is also an Advisor at Zen Legal LLP, a boutique law firm along with having a robust independent legal practice. He is also a mentor who believes in the philosophy that a telling and positive difference to the world can be made together, besides all things law, he is an avid sports enthusiast, foodie and techie." },
    { name: "Raghvendra Verma", title: "Group Head \u2013 Legal, ISON Group", image: `${IMG}/raghvendra-verma.jpg`, bio: "Raghwendra Verma has over 20 years of experience as a Corporate Legal Leadership. His gamut of experience includes cross-border M&A, Privacy Laws, Cyber Security, Strategy, Compliance, Contract Negotiations, Litigation, Risk Management. In a career spanning 20 years, Raghwendra delivered business-driven Legal strategy at global, regional and national levels across several industry verticals. Currently, he is Serving ISON as Group Head- Legal, Compliance and Corporate Secretary. ISON Group is into IT & ITES and has business operations in 29 countries across Africa, Middle East and India." },
    { name: "Moutaz Abdullat", title: "General Legal Counsel, Ferrero GCC", image: `${IMG}/moutaz-abdullat.jpg`, bio: "Moutaz Abdullat is currently employed at Ferrero GCC as General Legal Counsel. He is looking after Corporate Governance, Food Law, IP, Data Privacy and corporate commercial matters. Prior to Joining Ferrero, Moutaz was working at Nestl\u00e9 Middle East as Regional Legal Counsel covering the regions of Middle East, North of Africa & Maghreb. Moutaz obtained his LL.B degree from Al-Bayt University in Jordan and his Master's Degree in International Business Law from Paris Sorbonne University. In addition to his extensive experience in the above-mentioned fields, he is specialized in civil law, criminal law and international business laws." },
    { name: "Anshul Bharadwaj", title: "Practicing Advocate, High Court of Delhi", image: `${IMG}/anshul-bharadwaj.jpg`, bio: "Anshul is one of the early members of the Expandopedia Project of the Elements Global Services Company. Practicing advocate in the High Court of Delhi. He completed his bachelor's in Law & Business Administration from Guru Gobind Singh Indraprastha University, Delhi. Further, have a diploma in International Criminal Law from Case Western Reserve University & Diploma in Environmental Law from the University of North Carolina at Chapel Hill, NC." },
    { name: "Kanungo & Co", title: "Full-Service Law Firm, Mumbai / New Delhi / Jodhpur", image: null, bio: "Kanungo & Co is a law firm build on the foundation of dedication and professionalism. The firm has expanded its presence in India from Mumbai, New Delhi and Jodhpur." },
    { name: "Yusuke Hatakeyama", title: "Attorney, M&A in Southeast Asia", image: `${IMG}/yusuke-hatakeyama.jpg`, bio: "Yusuke is an attorney at law mainly engaged in M&A in Southeast Asia. He has also built up significant experience and expertise in trade law issues including WTO dispute settlement and proactive usage of free trade agreements/international investment agreements." },
    { name: "Sushmita Gandhi", title: "Specialist, Banking & Finance Disputes", image: `${IMG}/sushmita-gandhi.jpg`, bio: "Sushmita has over 13 years of extensive experience advising clients on a variety of commercial disputes across sectors, including Banking & Finance, Insolvency & Restructuring related matters and arbitrations including construction contracts arbitrations. She has advised lenders, borrowers, advisors, and other intermediaries in complex local and cross-border financing transactions across major debt financing disciplines. Sushmita has handled several domestic and international arbitrations, representing clients in institutional arbitrations in India and abroad. She has also advised on corporate and commercial disputes, appearing before a variety of forums, courts, and tribunals." },
    { name: "Kritika Seth", title: "IP & Entertainment Law Specialist", image: `${IMG}/kritika-seth.jpg`, bio: "Within a brief period of over 8 years, she has managed to stand out in both, Contracting as well as Litigation. She is known to regularly advise and represent various songwriters, music producers, singers, film directors, actors, authors, screenwriters, production houses, independent record labels and publishers. Ms. Seth's work further includes negotiating and advising digital and technology platforms, amongst others. Her key role with her clientele is of advising, structuring, and negotiating deals across all domestic and international production houses and platforms. Ms. Seth is currently involved in various projects related to IP rights management, documentation, and negotiation for the acquisition of content." },
    { name: "Sarthak Sarin", title: "Partner, Khaitan and Co", image: `${IMG}/sarthak-sarin.jpg`, bio: "Sarthak Sarin is a partner in Khaitan and Co's corporate and commercial practice group. Sarthak has received B.B.A. LL.B. degree from Symbiosis Law School (Pune) and his MSc. in Law and Finance degree from St Anne's College, University of Oxford (UK). Sarthak's practice spans a range of areas including mergers and acquisitions, assets and business transfers and joint venture transactions and he regularly acts as a strategic advisor on particularly complex and often market-leading control deals, growth capital investments, collaborations and exits transactions in India" },
    { name: "Brunda Lavu", title: "IP Lawyer, Trademarks & Copyright", image: `${IMG}/brunda-lavu.jpg`, bio: "Ms. Brunda Lavu is a Lawyer whose practice focuses on trademarks and copyright. She graduated with her BA. LLB (Bachelors of Arts and Law) from Bangalore Institute of Legal Studies, India. Immediately after graduation, she began practicing in the Andhra Pradesh High Court for a year. Thereafter, she pursued her LLM (Masters in Intellectual Property Law) from the University of Washington School of Law, Seattle, United States of America. While pursuing her LLM, she interned at the Washington Attorney General's Office under the Assistant Attorney General in the trademark and copyrights department for about a year which gave her diverse exposure and a fresh outlook to the evolving area of IPR as a key asset for the clients. Upon returning to India, Brunda worked independently for two years assisting various start-ups, mid-sized companies on legal matters." },
    { name: "Sandeep Grover", title: "Senior Advocate, Dispute Resolution", image: `${IMG}/sandeep-grover.jpg`, bio: "Sandeep has more than 15 years of dispute resolution experience and specializes in commercial and civil litigation and arbitrations. A significant part of his practice has been advising and representing clients in matters relating to patent and copyright infringement issues, joint venture, company and shareholder disputes, employment-related issues, merger and demerger schemes, insolvency, tender related disputes, white-collar crimes, real estate disputes, infrastructure and engineering disputes, other corporate and commercial disputes, debt recovery matters and consumer litigation. Sandeep regularly appears before the Supreme Court of India, High Courts across the country, the National Company Law Tribunal and National Company Law Appellate Tribunal, Appellate Tribunal for Electricity." },
    { name: "Marie-Laure Fathay", title: "Legal Director, Pharmaceutical Industry", image: `${IMG}/marie-laure-fathay.jpg`, bio: "A seasoned Legal Director, with extensive international and local experience in multinational pharmaceutical companies (Sanofi, GlaxoSmithKline, AstraZeneca, Janssen, Novartis). Latest position was Head of Legal at Novartis. In a previous professional life, specialized in commercial real estate and luxury retail (SCC, Emaar Malls Group, Al Tayer)." },
    { name: "Yogesh V Nayyar", title: "Founder, YVN & Associates", image: `${IMG}/yogesh-nayyar.jpg`, bio: "Yogesh has been practicing Law since last 26 years with clientele presence in UK, USA, Germany, UAE and India. With a view to cater the requirement of services in the field of Law, the firm YVN & Associates came into existence from Nagpur. Founded the firm in 2000 and its a full service Law Firm offering expertise in various legal areas. It is consistent, patient and professional, giving each new case our undivided attention whilst walking you through each step of the process. Nominated and appointed as \u201cMember of International Council of Jurists\u201d, London, in February, 2020. Nominated and appointed as \u201cOmbudsman & Arbitrator\u201d, Federation of Integrated Conflict Management (FICM) and Arbitrator, International Commercial Disputes Tribunal in 2017 and 2019." },
    { name: "Mansi Sinha", title: "Associate Partner, UCOL Advocates & Consultants", image: `${IMG}/mansi-sinha.jpg`, bio: "Mansi Sinha is a practicing attorney in India. She is working as a retained litigation lawyer, also the Associate Partner at UCOL, Advocates & Consultants, a pan India all service law firm. She is also regularly engaged as a legal and compliance consultant for India Bound, a niche GRC Firm in India, globally known as Worisgo. She has done her Bachelors of Law from Government Law College, Bombay, University of Mumbai. She also holds an MBA degree. In the short span of Mansi's career, she has had the opportunity of working with a variety of corporate entities and individuals, from Fortune 500 companies to small-scale businesses in India. Frequently advises on a wide range of arbitration matters." },
    { name: "Hisham Oweiss", title: "Head of Legal & Compliance, Samsung Electronics MENA", image: `${IMG}/hisham-oweiss.jpg`, bio: "Hisham Oweiss is currently working as Head of Legal and Compliance/Head of Government Affairs & Public Policy-MENA Region at Samsung Electronics. Earlier, Hisham was working at FRiENDi mobile as Legal Advisor." },
    { name: "Varsha Gupta", title: "Senior Legal Counsel, IDEMIA", image: `${IMG}/varsha-gupta.jpg`, bio: "Varsha is a dual qualified (India and England & Wales) corporate, commercial and privacy in-house lawyer with more than 13+ years of experience. She is currently working as Senior Legal Counsel for IDEMIA, a technology solutions provider, specialized in the provision of bank cards, SIM cards, end-to-end security protocols and emerging technologies relating to digital identity proofing, management and authentication. She possesses broad legal background; experience gained in an international law firm, FTSE 10-listed company, semi-government organization and a leveraged buyout. Adaptable and highly commercial lawyer, she is recognized for providing exceptional legal support and guidance across corporate transactional law, commercial contracts (including IP/IT contracts) and matters pertaining to compliance and regulations, as well as operating within international sanctions." },
    { name: "Ashish Suman", title: "Partner, J. Sagar Associates", image: `${IMG}/ashish-suman.png`, bio: "Ashish Suman is a partner with J. Sagar Associates, Law Firm. Ashish practices in the areas of Projects with a focus on Infrastructure and Transportation sector. His practice covers - Transport (automotive, rail, road & highways and civil aviation), Energy (Power & Hydrocarbons) and Social/Developmental projects. He is regularly advising on Infrastructure and PPP issues to several clients including various departments and ministries of the Government (central and state governments) and leading domestic and foreign Corporates. He has a broad legal background of more than 18 years of post-qualification experience in the Infrastructure Sector." },
    { name: "Michael Marlowe Uy", title: "Senior Associate, SKY Law Offices", image: `${IMG}/michael-marlowe-uy.jpg`, bio: "Michael Marlowe Uy is a Filipino lawyer who specializes in dispute resolution, corporate law, and media and technology law. He is currently a Senior Associate of SKY Law Offices, a member firm of Elite Global Legal Alliance (EGLA). Before joining SKY Law Offices, he previously worked as in-house counsel for one of the largest banks in the Philippines. He has extensive experience in representing individual and corporate clients before various courts, arbitral tribunals, and quasi-judicial agencies. He has also advised multinational corporations on matters relating to doing business in the Philippines." },
    { name: "Nitin Singh Bhati", title: "Startup Lawyer, Arbitrator & Mediator", image: `${IMG}/nitin-singh-bhati.jpg`, bio: "Experienced Startup lawyer, Arbitrator, Mediator, Negotiator, and Lawyer with a demonstrated history of working in the legal services industry for last 15 years. Strong legal professional skilled in ADR(Arbitration), Legal Writing, Corporate Law, Trials, Intermediary Protection, Cyber Law and Intellectual Property." },
    { name: "Kulwant Kaur", title: "General Counsel, TheCapitalNet", image: `${IMG}/kulwant-kaur.jpg`, bio: "Firm believer of the theory \u201cCreate your own path\u201d. Mother of two, wife to an entrepreneur, and general counsel at TheCapitalNet. She is an avid reader and likes to stay on top of the market developments and the industry particularly start-up and alternative investments ecosystem, she also follows legal developments in general, happening through various parts of the world. A classic example of breaking the professional timelines drawn by society when it comes to starting her professional journey." },
    { name: "Shahid Mehboob Jeena", title: "Co-Founder, Kaleidoscope Legal Services", image: `${IMG}/shahid-jeena.jpg`, bio: "Shahid is a Co-Founder and Managing Partner at Kaleidoscope Legal Services, Pune concentrating on comprehending and navigating the laws and regulations in the Indian financial sector. With a goal to bring in a change in the unorganized Banking legal sector so as to process files faster while maintaining the quality of the work provided, Shahid focuses on drafting Search and Title Reports, Notice of Intimation filing and registration of Mortgage Deeds in the office of Sub Registrar." },
    { name: "Arnav Shah", title: "Principal Associate, Cyril Amarchand Mangaldas", image: `${IMG}/arnav-shah.jpg`, bio: "Arnav Shah is a Principal Associate at Cyril Amarchand Mangaldas, where he practices in the general corporate group advising clients on inbound and outbound M&A and investments and other general corporate matters. Arnav specializes in advising on public M&A transactions namely takeovers, delisting and other corporate transactions involving listed companies. Arnav in his legal career has practiced as corporate lawyer at the law firms of Wadia Ghandy & Co. and Talwar Thakore & Associates, practicing in their Mumbai offices prior to practicing at Cyril Amarchand Mangaldas. Arnav graduated in 2010 from Government Law College, Mumbai, receiving his B.L.S.LLB and in 2015 he received his LLM with honors from the Columbia Law School, New York with a focus on corporate and securities laws." },
    { name: "Shrreyans Mehta", title: "Founder, Mehta And Mehta Law Firm", image: `${IMG}/shrreyans-mehta.png`, bio: "Shrreyans has done law specializing in finance and dispute resolution and now practicing tax litigation and dispute avoidance advisory. His firm, Mehta And Mehta Law Firm is backed by a team of experienced professionals, we provide assistance on a broad range of legal issues. We specialise predominantly in Taxation and Corporate Law. We believe in and strive towards quality services, professionalism, client satisfaction and above all, as speaks our motto (Parasparopagraho Jevanam), by and large repaying the society and the environment." },
    { name: "A. Gunaseelan", title: "Trial Lawyer, Madras High Court", image: `${IMG}/a-gunaseelan.jpg`, bio: "Enrolled as an Advocate with the Bar Council of Tamil Nadu on 20-02-1980 had extensive practice in Civil Litigations, starting as a Junior Advocate with Ms. D'Souza & Radhakrishnan 1980 \u2013 1988 and as a Senior Associate with Ms. King & Partridge 1988-1990, litigations relating to immovable properties, banking, contractual, services, labour disputes, and family disputes, and having mastered the art of being a Trial Lawyer commenced individual practice in 1990 and to this day continuously practising as Trial Lawyer in Civil Litigations at the Madras High Court and in the City Civil Court and various Subordinate Courts in the State of Tamil Nadu, India." },
    { name: "Antonio Ho", title: "Legal & External Affairs Counsel, BAT", image: `${IMG}/antonio-ho.png`, bio: "Antonio is an experienced legal counsel with a demonstrated history of working in both private practice and the in-house sector. Strong cross-area legal experience including criminal and commercial litigation, property law, cross-border corporate and commercial matters, regulatory shaping and lobbying, high profile cases management, and FMCG matters. Currently working as a legal and external affairs counsel overlooking the Hong Kong and Macao market on all commercial legal, regulatory lobbying, and compliance matters for British American Tobacco (\u201cBAT\u201d), the largest tobacco company globally as of 2020." },
    { name: "Harsh Bhagirath Buch", title: "Advocate, International Maritime & Space Law", image: `${IMG}/harsh-buch.png`, bio: "Mr. Buch's practice areas are Commercial & Corporate litigation, International Maritime Laws, Transportation & Trade Law, Dispute Resolution, Constitutional Law, Technology Media and Telecommunications and White Collar Crime. Mr. Buch is one of the few lawyers in India engaged in International Space Law both on the advisory and dispute resolution fronts. With vision set for preparing for the future of the Legal Industry, Mr. Buch has not limited his practice to the aforesaid and has expanded over the years in engaging himself in private clients based practice, advising and providing formal legal opinions to Governments both Indian & Foreign." },
    { name: "El Sayed Abdalla", title: "Senior Lawyer, UAE & Egypt", image: `${IMG}/el-sayed-abdalla.jpg`, bio: "He has an extensive legal experience gained over 23 years of practicing the law in two jurisdictions, in the Arab Republic of Egypt and the United Arab Emirates. He is admitted to the Egyptian Bar Association since year 1997. He has the right of audience before the Egyptian cassation court. His main areas of practice are Real Estate, Construction, Intellectual Property and Civil and Commercial Dispute Resolution in addition to his exceptional experience in commercial negotiations skills." },
    { name: "Chanchal Choudhary", title: "Advocate, Corporate & Industrial Law", image: `${IMG}/chanchal-choudhary.jpg`, bio: "Mr Choudhary has been dealing with corporate and industrial law since 1990 and has held several important positions in the corporate world and industrial undertakings of national and international repute. He has also been appearing regularly and arguing the matter before several tribunals such as the National Company Law Tribunal, Securities Appellate Tribunal, Debt Recovery Tribunal etc. and is empanelled as an advocate by several banks and finance companies of national and international presence." },
    { name: "Saifullah Khan", title: "International Trade & Policy Lawyer", image: `${IMG}/saifullah-khan.jpg`, bio: "Saifullah Khan is an international trade, IT and Policy lawyer, with 20 years\u2019 experience in international trade policy and law advisory, serving large client base in the domestic and international market. He is very successful and renowned anti-dumping lawyer not only in Pakistan but in various jurisdictions because of his rich experience and expertise in Trade Defense Laws of the WTO. He has been engaged in more than 85% of the antidumping investigations initiated by the Pakistani Antidumping Authority (i.e. National Tariff Commission, Ministry of Commerce \u2013 Pakistan) till date and has been providing trade remedial consultancy services to the domestic industry in Pakistan as well as a large number of foreign producers / exporters in various countries." },
    { name: "Khan Khalid Adnan", title: "Managing Partner, Khan Saifur Rahman & Associates", image: `${IMG}/khan-khalid-adnan.jpg`, bio: "Having completed his LLB (Hons) from University of London with a 1st class in 2007 and his Bar Vocational Course from BPP Law School (UK) in 2008, Khan Khalid Adnan was called to the Bar of England & Wales from the Lincoln's Inn. Since 2009 he started practising law in Bangladesh and in 2013 he got enrolled as an Advocate of the Supreme Court of Bangladesh. Barrister Adnan is the Managing Partner and Head of the Chamber of \u201cKhan Saifur Rahman & Associates\u201d and his areas of expertise are criminal law, judicial review, tort law including road traffic accident and clinical negligence cases, real estate law, corporate law, arbitration and mediation." },
    { name: "Wolora Afrin Rasna", title: "Founder, Women in IP Bangladesh", image: `${IMG}/wolora-afrin-rasna.jpg`, bio: "Wolora Afrin Rasna is a young dynamic social activist and an entrepreneur in the field of intellectual property. She was called to the Bar of England and Wales in 2012. She completed her Masters in Tax Management from University of Dhaka in 2019 and she is also an Accredited Mediator at ADR-ODR International. She is the founder and President of Women in IP Bangladesh, an organization for women empowerment." },
    { name: "Saira Nishtar", title: "In-House Legal Counsel, AkzoNobel", image: `${IMG}/saira-nishtar.jpg`, bio: "Experienced legal professional with a diverse portfolio in house and private practice experience with multinational corporations and regional and international laws firms in the Middle East. Saira started her in-house career as Legal Counsel for the electric power regulator in Pakistan and then moved on to work for law firms in the Middle East before moving back in-house at AkzoNobel which is the world's leading coatings and chemicals company." },
    { name: "Somesh Tiwari", title: "Managing Partner, Vardharma Chambers", image: `${IMG}/somesh-tiwari.jpg`, bio: "Somesh, is currently the Managing Partner at Vardharma Chambers. He has been practicing before the Hon'ble Supreme Court of India and the Hon'ble Delhi High Court in matters focusing on Arbitration, Banking, Company Law and Prevention of Money laundering Act. Mr. Tiwari has been appointed by the State Government of Uttar Pradesh and the State Government of West Bengal as panel counsel to represent the State Governments before the Hon'ble Supreme Court and the National Green Tribunal." },
    { name: "Nalina Mayegowda", title: "Co-Founder, Magnah Law Partners", image: `${IMG}/nalina-mayegowda.jpg`, bio: "Nalina has over 25 years of experience in the field of commercial litigation and dispute resolution. She has handled some of the complex corporate disputes and criminal litigation before the Apex court, High Courts, and various other Courts and Tribunals in India. She is a co-founder at Magnah Law Partners, which is based out of Bangalore with associated offices in major cities and she leads the dispute resolution team. Her experience in representing clients in most intricate and intertwined matters includes advising and representing clients as Counsel in cases involving protection of Intellectual Property Rights, issues arising under Company law, Information Technology matters and commercial disputes." },
    { name: "Nadim El Haj", title: "General Counsel & Board Secretary, UAE", image: `${IMG}/nadim-el-haj.jpg`, bio: "A no nonsense, result driven and strategic thinker with a demonstrated history in launching and turning around businesses in the Real Estate Development, Hospitality, Retail, TMT and Education industries. In-depth expertise in negotiating and closing mega transactions, including the structuring, development and acquisition of prime/trophy hospitality projects, real estate developments, retail, TMT and education projects in the MENA Region and on an international scale. Extensive experience working both in the Government and private sector in the UAE as General Counsel/Board Secretary and ExCo. member." },
    { name: "Iram Majid", title: "Executive Director, APCAM", image: `${IMG}/iram-majid.jpg`, bio: "Iram is executive director as well as empanelled arbitrator for APCAM (Asia Pacific Centre for Arbitration & Mediation). APCAM is an international ADR centre formed jointly by about ten arbitration and mediation centres from the Asia-Pacific countries, which host APCAM centres in their respective countries." },
    { name: "Pooja Prabhakar", title: "CEO & Managing Partner, BCP Associates", image: `${IMG}/pooja-prabhakar.jpg`, bio: "Pooja Prabhakar, as CEO & Managing Partner, develops and drives the vision & strategy at BCP Associates. After she moved to India from the US, where she held leadership positions at Fortune 50 companies, she took over the reins of BCP Associates where she envisioned and successfully rolled out enterprise programs in Legal Audit & Advisory, POSH & People Strategy across several large companies in India. Partnering with clients through innovative and disruptive service offerings across multiple verticals, Pooja has led the consistent, sustained, and diversified growth of BCP Associates. Her forte has been the innovative creation of Legal Technology that has widespread use in the industry today." },
    { name: "Soumitra Banerjee", title: "Partner, Fox Mandal", image: `${IMG}/soumitra-banerjee.jpg`, bio: "Highly revered in the commercial and financial services sector, Soumitra has vast experience advising clients on Corporate Finance including Debt Finance and Private Equity, Joint Venture setups and exits, Mergers & Acquisition including domestic and cross border acquisitions and General Corporate Matters. He is associated with one of India's oldest law firm Fox Mandal and is currently based out of Bangalore. With over 12 years of experience Soumitra is one of the youngest partners in his firm and oversees the expansion of the Corporate Commercial vertical of the firm in Bangalore, Mumbai and Pune." },
    { name: "Dr. Gehan Gunatilleke", title: "Founding Partner, LexAG, Sri Lanka", image: `${IMG}/gehan-gunatilleke.png`, bio: "Dr. Gehan Gunatilleke is a founding partner at LexAG, a law firm based in Colombo, Sri Lanka. Prior to co-founding LexAG, Gehan was a Research Director at the Colombo-based think tank, Verit\u00e9 Research. From 2015 to 2018, he served as an advisor to the Sri Lankan Foreign Ministry, where he specialised in international human rights treaty compliance. He was a member of the negotiation team that secured Sri Lanka's readmission to the European Union's Generalised Scheme of Preferences (GSP)+ trade concession facility in 2016. Gehan's doctoral thesis in law at the University of Oxford focused on state authority to limit individual freedom under international law." },
    { name: "Rishabh Gupta", title: "Partner, Prime Juris", image: `${IMG}/rishabh-gupta.jpg`, bio: "Rishabh is a partner of M/s. Prime Juris, Advocate & Solicitors, which primarily practices in Civil, Corporate and Commercial Litigation. Rishabh has served as lead counsel in several matters involving intricate and complex legal issues while representing various Corporate Houses, Financial Institutions, Startups and High-Net-Worth Individuals. With his years of experience, while working with various Senior Advocates and Tier 1 law firms, he has been exposed to multifarious and multifaceted legal issues. Post his LL.B from Vivekananda Institute of Professional Studies, Guru Gobind Singh Indraprastha University, Rishabh completed his Post-Graduate Diploma in Intellectual Property Rights and Masters in Corporate Law." },
    { name: "Ankit Sharma", title: "Company Secretary & Startup Lawyer", image: `${IMG}/ankit-sharma.jpg`, bio: "Ankit Sharma is a qualified Company Secretary and a Lawyer with over 10 years of experience in various diversified sectors like Energy, Real Estate, Travel, Ecommerce etc. He has been an active participant in industry-led dialogues and seminars. He is also a Guest Faculty for the Institute of Company Secretaries of India (ICSI) as well various other Educational Institutions. Working in the startup eco-system from over 7 years, Ankit had been instrumental in setting up the overall Legal functions for various Companies within the Industry." },
    { name: "Saurabh Bagaria", title: "Revenue & Tax Law Practitioner", image: `${IMG}/saurabh-bagaria.jpg`, bio: "Revenue/tax laws have always interested him. After having completed his LL.B and LL.M, he started his legal practice in Kolkata. Its been more than a decade's experience now. His areas of practice have predominantly been tax and allied laws including income tax, transfer pricing, GST, excise, customs, service tax, anti-dumping, VAT/sales tax, foreign exchange, benami property, black money, money laundering etc. He regularly practice before the Hon'ble Calcutta High Court. He also appear before Customs, Excise and Service Tax Appellate Tribunal, Income Tax Appellate Tribunal, West Bengal Taxation Tribunal and other quasi-judicial forums." },
    { name: "Puneet Bansal", title: "Tax & Compliance Advisor", image: `${IMG}/puneet-bansal.png`, bio: "Puneet has over 20 years of experience in advising leading multinational and Indian companies in setting up operations in India, structuring business models and supply chains, optimizing tax exposures, contract review and undertaking compliance with Indirect tax laws. He has a rich experience in litigation and has successfully represented clients' interest before various judicial fora across India." },
    { name: "Dr. Mina Adel Iskander", title: "Lawyer & Educator, Egypt", image: `${IMG}/dr-mina-iskander.jpg`, bio: "A self-motivated Lawyer who gained experience not only through studies but through hard work in different aspects of law, also gained different dimensions of experience through several family members who work as lawyers, judges and prosecutors. Practiced law in different aspects whether theoretically in teaching, serving and presenting the Governmental bodies or in the law firm. Experience is not limited to the local jurisdiction and legislation in Egypt, yet has wide experience in different legal transactions and aspects in the whole region." },
    { name: "Heena Khurana Nagpal", title: "Independent Director & Corporate Lawyer", image: `${IMG}/heena-khurana-nagpal.jpg`, bio: "Heena holds experience of over 11 years in the field of Corporate, Economic and Commercial laws. She is on the Board of Directors as an Independent Director in a Public Ltd Company which has varied businesses ranging from Real Estate, business of investment in shares and securities, Financial Advisory and providing loans and advances. She is a seasoned professional in the areas of Company Law, Secretarial functions, Intellectual Property Laws, PoSH Law and HR Policies and Legal & Labour Compliances across State and Central statutes. She has an expert hand in liaisoning with Ministries and Govt. authorities." },
    { name: "Vineet Aneja", title: "Managing Partner, Corporate Commercial Practice", image: `${IMG}/vineet-aneja.jpg`, bio: "Vineet is the managing partner as well as a head of Corporate Commercial practice of the firm. He has a plethora of experience across sectors such as corporate commercial, mergers & acquisitions, joint ventures, private equity, compliance audit, retail, hospitality, employment, e-commerce, education, healthcare, aviation, white collar crimes, etc. He has provided specialized transactional and advisory services across sectors, covering diverse areas. He has been a director on the board of Indian subsidiaries of various multinational companies. To name a few, Vineet has been a director on the Board of Crate & Barrel, Renold, Continental, Contract Pharmacal, Superdry, Manuli Hydraulics." },
    { name: "Garima Sharma", title: "Corporate Lawyer, J. Sagar Associates", image: `${IMG}/garima-sharma.jpg`, bio: "Garima Sharma is a corporate lawyer, currently based out of Hyderabad, India. While she has been practicing law for the last 4 years, she has been a law enthusiast for as long as she can remember. She graduated in Legum Baccalaureus from Symbiosis International University, Pune & has worked with Tatva Legal, Hyderabad prior to being associated with J. Sagar Associates, Hyderabad. Her areas of primary focus include domestic & foreign investments, mergers, acquisitions, joint ventures, debt & equity financing, restructuring, corporate commercial transactions, master services arrangements & infrastructure projects." },
    { name: "Alizeh Iqbal Haider", title: "Corporate-Commercial Specialist, UAE", image: `${IMG}/alizeh-iqbal-haider.jpg`, bio: "Alizeh has over eighteen years of experience in both in-house and private practice. Alizeh has held leadership roles in legal and compliance functions at large regional corporations and family-owned businesses in the UAE and across the MENA region. Alizeh is a specialist in corporate-commercial advisory, drafting and negotiating contracts, ethical compliance and corporate governance. Alizeh has strong experience in intellectual property law, corporate-commercial laws, real estate law and banking law. Her deep understanding of UAE and regional laws and regulatory practices, as well as cultures across the region has led to a distinguished career." },
    { name: "Sagar Sharma", title: "IP Litigation Associate, RNA Technology", image: `${IMG}/sagar-sharma.jpg`, bio: "Sagar is an Associate handling the responsibility in the IP litigation team at RNA, Technology and IP Attorneys. He completed his legal studies in 2015 and became a member of Bar Council of India. In 2020 Sagar joined RNA Technology and IP Attorneys; a full-service IP law firm as Litigation associate. He was made part of the litigation team as the firm saw his inclination and perspicacity towards Intellectual Property knowledge and enthusiasm to be part of this culture." },
    { name: "Daphne Chandrika Peiris", title: "Senior Partner, D&D Law Chambers, Colombo", image: `${IMG}/daphne-peiris.jpg`, bio: "Daphne is Senior Partner at D&D Law Chambers, Colombo. She is an active legal practitioner in the Courts of the first instance and in Appeal Courts. She is a Legal consultant in Banking & Finance Law, Company, Company Secretarial and Dispute resolution, Land Law, Investment by Foreigners in Sri Lanka and Industrial and Labour Relations." },
    { name: "Mansi Bathiya", title: "IP & Data Protection Specialist", image: `${IMG}/mansi-bathiya.jpg`, bio: "Mansi is a certified practitioner of law and a Member of Bar Council of Maharashtra & Goa. She has extensive experience in Data Protection & Intellectual Property Rights with more than 500 marks under her management, she as a practice leader of the vertical in her firm extends end-to-end support to her clients; right from registration & management to protection & representation including drafting, diligence, assignment, and valuation advisory services pertaining to complex IP M&A transactions. She has authored two books on the subject namely \u201cImportant Concept of Copyright Law & Its Registration Process in India\u201d & \u201cEntrepreneur's Guide for Conceptual Understanding of Trademark and Its Registration Process in India\u201d and she is also an educator." },
    { name: "Dr. Sheetal Babar", title: "Academician & Legal Consultant, Pune", image: `${IMG}/dr-sheetal-babar.jpg`, bio: "Adv. Dr. Sheetal Babar, is an academician and a legal consultant since 2003. She has work experience in legal education for more than 17 years. She is a Senior Legal Partner in APJ Legal and Associates, Pune. She has been associated with many esteemed educational institutions such as DES NF Law College, MIT School of Management and Department of Law, Savitribai Phule Pune University. She is a passionate law academician, with her own company, Lawstraw Private Limited, dedicated for virtual courses not only benefitting law students but categories such as Teachers, Women, Children etc. She has conducted workshops for primary and secondary teachers along with Law professors on various skills." },
    { name: "Nitin Kumar Bhatnagar", title: "Founder, NKB LEGAL", image: `${IMG}/nitin-bhatnagar.jpg`, bio: "Nitin Kumar Bhatnagar, a practicing Advocate and the founder and Managing Partner of NKB LEGAL, a full-service law firm located in New Delhi and having Associate network in all major parts of the country, is a 41-year-old professional with over fifteen years of working experience overall and more than ten years in active litigation, out of which about seven years in Independent litigation practice when he founded the Law Firm NKB LEGAL in the year 2014 after working for a prominent IP Law Firm in New Delhi, India. Before setting up an independent practice, he worked in the IP litigation and enforcement department and has successfully carried out several IP enforcements and criminal raid operations for some of the biggest corporate." },
    { name: "Reema Aref", title: "Senior Manager, Ernst & Young Riyadh", image: `${IMG}/reema-aref.png`, bio: "Reema's practice focuses on Tax litigation, Tax dispute resolution and Tax controversy from the objection stages to Tax appeals before Tax Judicial Committees, currently working in Ernst & Young Riyadh as a Senior Manager \u2013 Corporate and Tax Law, in Business Tax Advisory. She has extensive trial and appellate advocacy experience and has regularly appeared before the Alternative dispute resolution committees, Tax Judicial committees." },
    { name: "Pavestones Legal", title: "Full-Service Law Firm, Nigeria", image: null, bio: "Pavestones is a client focused, solution driven and commercially savvy law practice, providing innovative, quality, timely and tailored legal solutions to its esteemed clients. Our practice was borne as a result of a desire to meet the legal requirements of businesses by adopting a modern, cost effective and less archaic approach. We are, therefore, more flexible than the traditional law firms. We provide legal advisory services and transactional support across various industries including Manufacturing, Real Estate, Aviation, Energy, Telecommunications, Technology, Entertainment, Banking and Finance, Pharmaceutical, Health and Data Protection. We represent SMEs, large and multinational corporations." },
    { name: "Bharat Raichandani", title: "Senior Advocate, Supreme Court of India", image: `${IMG}/bharat-raichandani.jpg`, bio: "Bharat has over 16 years of experience in arguing cases before the Supreme Court and various High Courts of the country. He has successfully argued over 1000 cases before the CESTAT at Mumbai, Delhi, and various Indian states." },
    { name: "Revathy Muralidharan", title: "M&A and Private Equity Specialist", image: `${IMG}/revathy-muralidharan.jpg`, bio: "Revathy's core practice area is Mergers & Acquisitions and Private Equity Investments. She also specializes in General Corporate Commercial, Domestic and Cross Border Investments, Corporate Restructuring, Employment and Compliance. She has advised several clients in structuring and negotiating several transactions, including share acquisitions and business transfers across various sectors such as manufacturing, energy (renewable and conventional), real estate, healthcare, services, automotive and information technology. She regularly advises clients including foreign funds and Indian promoters on the Indian foreign exchange control laws in connection with both inbound and outbound investments." },
];
